quiz.answer:
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
	Age  int    `json:"age"`
}

// ---- ここから下は「*sql.Rows の代わり」。変えなくてよい ----

type Rows struct {
	data   [][]string
	i      int
	Closed bool
}

func (r *Rows) Next() bool {
	if r.Closed || r.i >= len(r.data) {
		return false
	}
	r.i++
	return true
}

func (r *Rows) Scan(dest ...any) error {
	row := r.data[r.i-1]
	if len(dest) != len(row) {
		return fmt.Errorf("sql: expected %d destination arguments in Scan, not %d", len(row), len(dest))
	}
	for k, d := range dest {
		switch p := d.(type) {
		case *int:
			n, err := strconv.Atoi(row[k])
			if err != nil {
				return fmt.Errorf("sql: Scan error on column index %d: converting %q to int", k, row[k])
			}
			*p = n
		case *string:
			*p = row[k]
		default:
			return fmt.Errorf("sql: Scan error on column index %d: destination not a pointer", k)
		}
	}
	return nil
}

func (r *Rows) Close() error {
	r.Closed = true
	return nil
}

// ---- ここまで ----

func listUsers(rows *Rows) ([]User, error) {
	defer rows.Close()

	users := []User{}
	for rows.Next() {
		var u User
		if err := rows.Scan(&u.ID, &u.Name, &u.Age); err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, nil
}

func main() {
	rows := &Rows{}
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		if f := strings.Split(sc.Text(), ","); len(f) == 3 {
			rows.data = append(rows.data, f) // SELECT id, name, age FROM users の 1 行
		}
	}
	users, err := listUsers(rows)
	if err != nil {
		fmt.Println("500", err)
	} else {
		b, _ := json.Marshal(users)
		fmt.Println(string(b))
	}
	fmt.Println("closed:", rows.Closed)
}

quiz.explanation:
模範解答は次のとおりです。

```go
func listUsers(rows *Rows) ([]User, error) {
	defer rows.Close()

	users := []User{}
	for rows.Next() {
		var u User
		if err := rows.Scan(&u.ID, &u.Name, &u.Age); err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, nil
}
```

よくある書き間違いは 3 つあります。`rows.Close()` を defer にせず最後に書くと、3 つ目のテスト(2 行目の age が数字でない)で途中の return を通るので `closed: false` になります。`var users []User` で始めると、2 つ目のテスト(0 行)で `null` になります。Scan の引数を `&u.Name, &u.ID, &u.Age` の順にすると、1 列目の id が Name に、2 列目の name が ID に入ろうとしてエラーになります。Scan は SELECT の列の順に書き込みます。
